func quotaSelected(c ProfileConfig, f QuotaUsageFilter, account string, at int64) bool {
	if f.Profile == "" {
		return true
	}
	assigned := false
	for _, p := range c.Profiles {
		if !quotaProfileContains(c, p, account, at) {
			continue
		}
		assigned = true
		if p.ID == f.Profile || f.Profile == "all" && !p.Archived {
			return true
		}
	}
	return f.Profile == "unassigned" && !assigned
}

func quotaWindowSelected(c ProfileConfig, f QuotaUsageFilter, w Window) bool {
	if f.Profile == "" {
		return true
	}
	for _, p := range c.Profiles {
		if p.ID != f.Profile && !(f.Profile == "all" && !p.Archived) {
			continue
		}
		if p.Memberships != nil {
			for _, m := range p.Memberships {
				if m.Account == w.Account && intervalsOverlap(Binding{Start: m.Start, End: m.End}, Binding{Start: w.Start, End: w.AttributionEnd}) {
					return true
				}
			}
		} else if p.Selection {
			if quotaProfileContains(c, p, w.Account, w.Start) {
				return true
			}
		} else {
			for _, b := range c.Bindings {
				if b.Profile == p.ID && b.Account == w.Account && intervalsOverlap(b, Binding{Start: w.Start, End: w.AttributionEnd}) {
					return true
				}
			}
		}
	}
	return f.Profile == "unassigned" && quotaSelected(c, f, w.Account, w.Start)
}

