func (s *Service) QuotaEvidence(ctx context.Context, f QuotaUsageFilter) (QuotaUsageEvidence, error) {
	out := QuotaUsageEvidence{}
	if err := s.acquireHistory(ctx); err != nil {
		return out, err
	}
	defer s.releaseHistory()
	initialRevision := f.At > 0 && f.Revision == 0
	var err error
	f.ProfileFilter, err = s.pinProfileFilter(ctx, f.ProfileFilter)
	if err != nil {
		return out, err
	}
	revision := f.Revision
	if initialRevision {
		revision = -1
	}
	c, err := s.ProfileConfig(ctx, revision)
	if err != nil {
		return out, err
	}
	f.Revision = c.Revision
	out.PriceBook, err = s.comparisonPriceBook(ctx, f.ValuationRule)
	if err != nil {
		return out, err
	}
	f.ValuationRule = out.PriceBook.ID
	p, err := s.proofForValue(ctx, f.WindowID, f.Through, f.ObservationsThrough, f.At, out.PriceBook)
	if err != nil {
		return out, err
	}
	windowSelected := quotaWindowSelected(c, f, p.Window)
	if f.Profile == "unassigned" {
		for _, e := range p.Events {
			if quotaSelected(c, f, e.Account, e.Started) {
				windowSelected = true
				break
			}
		}
	}
	if !windowSelected || f.Account != "" && f.Account != p.Window.Account || f.From > 0 && p.Window.Reset <= f.From || f.To > 0 && p.Window.Start >= f.To || f.Kind != "" && f.Kind != p.Window.Kind {
		return out, errors.New("window is outside the selected profile or period")
	}
	if err = s.enrichTokenEvidence(ctx, p.Events, out.PriceBook, f.TokenEvidenceThrough); err != nil {
		return out, err
	}
	decision := windowValuation(p.Window, out.PriceBook)
	if out.PriceBook.Policy == profileValuePolicy {
		out.Valuation = &decision
	}
	for i := range p.Events {
		v := valueWindowEvent(p.Events[i], out.PriceBook, decision)
		p.Events[i].Value = &v
	}
	meterEvents, meterObs, err := s.evidence(ctx, p.Window.Account, f.Through, f.ObservationsThrough)
	if err != nil {
		return out, err
	}
	if err = s.enrichTokenEvidence(ctx, meterEvents, out.PriceBook, f.TokenEvidenceThrough); err != nil {
		return out, err
	}
	out.MeterObservations = []Observation{}
	for _, o := range meterObs {
		if o.Kind == p.Window.Kind && o.Scope == p.Window.Scope && o.Observed >= p.Window.Start && o.Observed < p.Window.AttributionEnd {
			out.MeterObservations = append(out.MeterObservations, o)
		}
	}

	out.Normalization = normalizeProfileWindow(p.Window, out.MeterObservations, meterEvents, out.PriceBook, f.ProfileFilter, normalizationPeriods(c, f.Profile, p.Window.Account, p.Window, f.ProfileFilter))
	models := map[string]*ProfileTotals{}
	selected := []Event{}
	for _, e := range p.Events {
		if quotaSelected(c, f, e.Account, e.Started) && keyMatches(e, f.APIKey) && (f.Model == "" || f.Model == e.Model) {
			selected = append(selected, e)
			out.Value.add(*e.Value)
			addBucket(models, e.Model, e)
		}
	}
	out.Models = buckets(models)
	p.SharedEvents, p.SharedReconciled = p.Events, p.Reconciled
	p.Events = selected
	p.Window = profileContribution(p.Window, selected)

	p.Window.TokensPerPercent, p.Window.EstimatedLimit, p.Window.EstimatedRemaining, p.Window.Exhaustion = nil, nil, nil, nil
	p.Window.CalibrationDelta = nil
	p.Window.CalibrationTokens, p.Window.CalibrationStart, p.Window.CalibrationEnd = 0, 0, 0
	p.Window.Notes = []string{"Quota observations and captured prices are retained as evidence. Quota percentages are account-level readings; selected requests may be only a contribution to the account."}
	var totals ProfileTotals
	for _, e := range selected {
		totals.add(e)
	}
	p.Reconciled = totals.Requests == p.Window.Requests && totals.Tokens == p.Window.Tokens && totals.CostNano == p.Window.CostNano
	p.Policy = "Recorded requests use the whole provider window and saved credential dates. Normalized values use only the displayed pair of quota readings and one pinned price book. Each model/category is priced separately; reasoning is included in output once. Unknown Claude write TTL is bounded by 5m/1h rates. Selected and shared events overlap. Captured prices/costs remain separate audit evidence."
	if out.Valuation != nil {
		p.Policy += " Window valuation is contextual: assumed_5m applies only to the pinned historical cohort and unknown remainder. Source tokens, captured costs and global event values are not rewritten. See valuation and price_book.historical for cutoff, H and checkpoint."
	}
	out.Proof, out.Filter = p, f
	return out, nil
}
